const e=[{id:1,code:"GOV-101",icon:"DoorOpen",accent:"#2563eb",title:"Emergency Evacuation Plan",subtitle:"Emergency Evacuation Plans",summary:"Creating an evacuation plan for government offices and buildings",blocks:[{body:"The emergency evacuation plan is one of the most important documents of any government office. This plan protects the lives of staff and visitors during incidents such as fires, earthquakes or chemical hazards."},{heading:"1. Steps for Creating the Plan",body:"A successful plan requires these steps:",points:["Floor plan: prepare a complete floor plan of the building showing the evacuation routes and the locations of fire extinguishers","Evacuation routes: every floor must have at least two exit routes located far apart from each other (NFPA 101), and exit doors must open from the inside without a key","Assembly point: a safe location outside the building, at a recommended distance of at least 50 meters","Responsibility: designate an evacuation warden for every floor","Alarm system: a fire bell or siren that can be heard on all floors","Drills: a practical evacuation drill once every 3 months"]},{heading:"2. Rules for Safe Evacuation",body:"When the alarm sounds:",points:["Walk calmly and in an orderly manner — do not run","Do not use the elevator — exit by the stairs only","If there is smoke, stay low and crawl beneath the smoke","Before opening a door, test it with the back of your hand — if it is hot, do not open it and find another route","Help people who need assistance and close doors behind you","Go directly to the assembly point and remain there"]},{heading:"3. The Role of Wardens",body:"Every floor needs a fire warden:",points:["Fire Warden: the person with primary responsibility for the floor","Checks all rooms (including restrooms and storerooms) so that no one is left behind","Directs people to the evacuation routes","Counts people at the assembly point and informs the 115 team"]}],media:[{kind:"image",src:"media/images/gov_evacuation.png",title:"Evacuation Floor Plan",description:"Example of a floor plan"}],quiz:[{question:"How far from the building is the assembly point recommended to be?",options:[{text:"10 meters",correct:!1},{text:"25 meters",correct:!1},{text:"50 meters",correct:!0},{text:"100 meters",correct:!1}],explanation:"At least 50 meters, so that it is away from falling glass, debris and smoke and does not block the route of emergency vehicles."}]},{id:2,code:"GOV-102",icon:"FileLock",accent:"#059669",title:"Document Protection",subtitle:"Document Protection",summary:"Procedures for protecting important documents from fire and water",blocks:[{body:"Government documents are a valuable asset. Losing them to fire or water can halt the work of an office and destroy people's rights. For this reason, protecting and copying them is essential."},{heading:"1. Classifying Documents",body:"Determining the importance of documents:",points:["Level A — very important: contracts, financial, legal","Level B — important: reports and official letters","Level C — routine: unofficial correspondence"]},{heading:"2. Physical Protection",body:"Physical protection measures:",points:["Fire-resistant safes: for Level A documents","Locked metal cabinets, raised above the floor","Waterproof plastic bags and boxes","Environmental control: a cool, dry location with stable temperature and humidity"]},{heading:"3. The 3-2-1 Rule for Backup Copies",body:"The 3-2-1 rule:",points:["3 copies of all important data","2 different types of storage (media)","1 copy at another location, outside the building"]}],media:[{kind:"image",src:"media/images/gov_backup.png",title:"Backup Copies",description:"The 3-2-1 rule"}],quiz:[{question:"What does the 3-2-1 rule mean?",options:[{text:"3 computers",correct:!1},{text:"3 copies, 2 types of media, 1 off-site",correct:!0},{text:"3 days",correct:!1},{text:"3 employees",correct:!1}],explanation:"3 copies on 2 types of media, and 1 copy at another location outside the building."}]},{id:3,code:"GOV-103",icon:"Zap",accent:"#ca8a04",title:"Electrical Safety",subtitle:"Electrical Safety",summary:"Electrical hazards in offices and the inspection of equipment",blocks:[{body:"Electricity is one of the main causes of fires in offices. Old wiring, overloaded outlets and heating appliances must be inspected regularly."},{heading:"1. Electrical Hazards",body:"Common hazards in offices:",points:["Overloading: too many devices on a single outlet","Old cables with cracked or damaged insulation","Water near electrical devices and outlets","Extension cords: heavy and permanent use"]},{heading:"2. Safety Rules",body:"Daily rules:",points:["Do not connect one extension cord to another extension cord","Your hands must be dry before touching an outlet","Plug heaters directly into the wall outlet, not into an extension cord"]},{heading:"3. Electrical Fires",body:"If a fire starts in an electrical device:",points:["If you can do so safely, cut the power at the electrical panel and call 115","If the fire is small and you are trained, use a CO₂ or dry powder (ABC) fire extinguisher, with your exit behind you; otherwise get out","No water or foam unless the label shows a Class C rating or an electrical-test marking — there is a risk of electric shock"]}],media:[{kind:"video",src:"media/videos/gov_electrical.mp4",title:"Electrical Safety",description:"Guidance"}],quiz:[{question:"Which fire extinguisher is best for an electrical fire?",options:[{text:"Water",correct:!1},{text:"Foam",correct:!1},{text:"CO₂ or dry powder",correct:!0},{text:"Blanket",correct:!1}],explanation:"CO₂ and dry powder do not conduct electricity; ordinary water and foam conduct electricity and can cause electric shock."}]},{id:4,code:"GOV-104",icon:"HeartPulse",accent:"#dc2626",title:"First Aid Program",subtitle:"First Aid Program",summary:"Forming a first aid team and preparing supplies",blocks:[{body:"Every office needs a first aid program. It is recommended to have at least one trained person on every floor and on every shift, and more in large offices."},{heading:"1. The First Aid Team",body:"Team composition:",points:["At least one trained person on every floor and on every shift","An approved course in first aid, cardiopulmonary resuscitation (CPR) and AED","Renewal of training and certification every 2 years"]},{heading:"2. The First Aid Kit",body:"Required supplies:",points:["Bandages and sterile gauze","Antiseptic wound-cleaning solution","Scissors and tweezers","Disposable medical gloves","A CPR mask for giving breaths safely"]},{heading:"3. Cardiopulmonary Resuscitation (CPR)",body:"CPR steps for adults:",points:["1. If the person is unresponsive and not breathing normally: call 122 and ask for an AED; place the person on their back on a firm surface","2. 30 chest compressions in the center of the chest: depth 5–6 cm, rate 100–120 compressions per minute","3. 2 breaths (each about 1 second) if you are trained; if not, give chest compressions only","4. Continue at a ratio of 30:2 until an AED or the ambulance arrives; use the AED immediately"]}],media:[{kind:"video",src:"media/videos/gov_cpr.mp4",title:"Cardiopulmonary Resuscitation (CPR)",description:"How to perform CPR"}],quiz:[{question:"In CPR, how many chest compressions are given before the 2 breaths?",options:[{text:"10",correct:!1},{text:"15",correct:!1},{text:"30",correct:!0},{text:"50",correct:!1}],explanation:"The correct ratio for adults is 30:2 (AHA 2025)."}]},{id:5,code:"GOV-105",icon:"Flame",accent:"#ea580c",title:"Fire and Fire Extinguishers in Offices",subtitle:"Fire Prevention & Extinguisher Use",summary:"Preventing fires and using fire extinguishers in government buildings",blocks:[{body:"Fires in offices are a serious hazard. Paper, computers, old wiring and electrical overloading are the main causes of fire. A prevention and preparedness program protects the lives of staff and public property."},{heading:"1. Causes of Fire in Offices",body:"Main causes:",points:["Electrical overloading: too many devices on a single outlet","Paper and documents: materials that burn easily","Cigarettes and matches: a major cause of fires breaking out","Stoves and portable heaters: a winter hazard","Small kitchens: while making tea and coffee","Batteries and chargers: overheating"]},{heading:"2. Types of Fire Extinguishers",body:"Offices need these types:",points:["Dry powder (ABC) fire extinguisher: for Class A, B and C fires — not for metals (D) and not for cooking oil (K)","CO₂ fire extinguisher: for fires in electrical equipment — does not damage computers","Water fire extinguisher: for Class A only (paper, wood, cloth) — not for electricity or oil","The UK code BS 5306-8 recommends at least two fire extinguishers on each floor (very small floors excepted); the rule for offices in Duhok is set by the Civil Defense Directorate and is not yet confirmed","Place fire extinguishers near doors and along evacuation routes","Monthly visual check (pin and seal intact, label readable, pressure gauge in the green if there is one; CO₂ extinguishers have no gauge, so lift one to feel that it is full) and yearly inspection and maintenance by a qualified person (NFPA 10)"]},{heading:"3. The PASS Technique",body:`Before you use an extinguisher (every answer must be yes):
• The fire is small and just starting, like a fire in a wastebasket or a pan.
• The extinguisher is the right type for this fire.
• Your exit is behind you and the fire is not between you and the exit.
• The alarm has been raised: others are warned and 115 has been called.
• You are trained to use the extinguisher.
• No smoke or heat is blocking your way out.
• If the fire does not go out at once, stop, get out and close the door behind you.

PASS is the general method for most hand-held extinguishers. Class D, wet chemical, clean agent and wheeled units: follow the label and the manufacturer's instructions. How to use a fire extinguisher:`,points:["P = Pull: pull out the safety pin","A = Aim: aim the nozzle at the base of the fire","S = Squeeze: squeeze the extinguisher handle firmly","S = Sweep: sweep from side to side at the base of the fire","Distance: start from the distance shown on the extinguisher label or in the manufacturer's instructions, with your exit behind you, and move closer only as the fire gets smaller","Keep your exit behind you; if the fire does not go out at once or starts to spread, get out, close the door behind you and make sure 115 has been called"]},{heading:"4. Alarm Systems",body:"Systems required in offices:",points:["Fire siren: must be audible on every floor","Manual alarm button (Pull Station): near the exits","Smoke detection: as required by the building's fire code (the requirement for Duhok offices is not yet confirmed)","Emergency lighting: switches on automatically when the power goes out","Post the number 115 on the wall of every room"]}],media:[{kind:"video",src:"media/videos/gov_fire_prevention.mp4",title:"Fire Prevention",description:"Complete guidance for offices"},{kind:"image",src:"media/images/gov_pass_method.png",title:"The PASS Technique",description:"Step by step"},{kind:"image",src:"media/images/gov_extinguisher_types.png",title:"Types of Fire Extinguishers",description:"ABC, CO₂, water"}],quiz:[{question:"Which fire extinguisher is best for a computer fire?",options:[{text:"Water fire extinguisher",correct:!1},{text:"CO₂ fire extinguisher",correct:!0},{text:"Foam fire extinguisher",correct:!1},{text:"A blanket",correct:!1}],explanation:"CO₂ does not damage computers and does not conduct electricity."},{question:"In the PASS technique, what does A stand for?",options:[{text:"Alert",correct:!1},{text:"Aim",correct:!0},{text:"Action",correct:!1},{text:"Away",correct:!1}],explanation:"A = Aim: aim the nozzle at the base of the fire."},{question:"The UK code BS 5306-8 recommends at least how many fire extinguishers on each floor?",options:[{text:"1 fire extinguisher",correct:!1},{text:"2 fire extinguishers",correct:!0},{text:"3 fire extinguishers",correct:!1},{text:"5 fire extinguishers",correct:!1}],explanation:"The UK code BS 5306-8 recommends at least two fire extinguishers on each floor (very small floors excepted), and the travel distance to reach them must also stay within the limit. The rule for offices in Duhok is set by the Civil Defense Directorate and is not yet confirmed."}]},{id:6,code:"GOV-106",icon:"Activity",accent:"#d97706",title:"Earthquakes in Government Buildings",subtitle:"Earthquake Safety in Government Buildings",summary:"How to protect yourself and evacuate safely during an earthquake",blocks:[{body:"The Kurdistan Region lies in a seismically active zone. Government buildings, especially older ones, are at risk. Preparedness and knowledge of the procedures save lives."},{heading:"1. During an Earthquake",body:"If you are inside the office:",points:["Drop: immediately drop onto your hands and knees","Cover: get under a sturdy table, away from windows and heavy cabinets (not in a doorway), and protect your head and neck","Hold On: hold on to the table leg until the shaking stops","Do not run outside — many injuries happen while running and from falling debris","Do not use the elevator — it may stop and trap you inside","If you are in an open area: stay away from buildings, power lines and poles"]},{heading:"2. After an Earthquake",body:"Steps after an earthquake:",points:["Check yourself and your colleagues for injuries","Exit by the stairs (not the elevator!)","If you smell gas or hear gas escaping: get out and call 115 from outside; only trained, designated staff shut off the gas at the main valve, and only if they can reach it safely, without entering the area where the gas has collected and without operating any switch","Go to the assembly point and count people","If there are injured people or people trapped under rubble, call 115 and 122","Be alert for aftershocks","Do not go back into the building until experts have confirmed that it is safe"]},{heading:"3. Advance Preparedness",body:"Required preparations:",points:["Prepare an earthquake plan and post it on the wall","Secure cabinets, shelves and heavy equipment to the wall","Prepare an emergency kit on every floor","Annual inspection of the building by a qualified engineer","Drop, Cover, Hold On drill every 3 months","Designate two assembly points (one near and one far)"]},{heading:"4. Responsibilities of Managers",body:"Managers must:",points:["Designate an earthquake warden for every floor","Keep a staff list ready for headcounts","Establish a special plan for people with special needs","Inspect the alarm system regularly","Post the emergency numbers (115, 122, 104) in every room"]}],media:[{kind:"video",src:"media/videos/gov_earthquake.mp4",title:"Earthquakes in the Office",description:"Practical drill"},{kind:"image",src:"media/images/gov_drop_cover_hold.png",title:"Drop, Cover, Hold On",description:"Step by step"}],quiz:[{question:"During an earthquake, what is the first thing to do?",options:[{text:"Run outside",correct:!1},{text:"Get into the elevator",correct:!1},{text:"Drop, Cover, Hold On",correct:!0},{text:"Open the windows",correct:!1}],explanation:"Drop under a sturdy table, cover yourself and hold on until the shaking stops."},{question:"After an earthquake, what do we use to exit the building?",options:[{text:"The elevator",correct:!1},{text:"The building's stairs",correct:!0},{text:"The windows",correct:!1},{text:"It makes no difference",correct:!1}],explanation:"Always exit by the stairs — the elevator may stop."},{question:"According to this program, how often is an earthquake drill required in the office?",options:[{text:"Every year",correct:!1},{text:"Every 6 months",correct:!1},{text:"Every 3 months",correct:!0},{text:"Only once",correct:!1}],explanation:"This program recommends conducting a practical drill once every 3 months."}]},{id:7,code:"GOV-107",icon:"Wind",accent:"#475569",title:"Gas Safety and Ventilation",subtitle:"Gas Safety & Ventilation",summary:"Gas hazards in offices and the importance of proper ventilation",blocks:[{body:"In winter, gas and kerosene stoves and heaters are widely used in offices. A gas leak can cause an explosion and fire, and incomplete combustion produces the toxic gas carbon monoxide (CO), which is colorless and odorless and can kill. Proper ventilation and recognizing the hazards save lives."},{heading:"1. The Danger of Carbon Monoxide (CO)",body:"CO is a silent killer:",points:["CO is colorless, odorless and tasteless — it cannot be detected by the senses","Symptoms: headache, dizziness, nausea and vomiting, confusion; then loss of consciousness and death","Sources: gas and kerosene stoves in rooms without ventilation","Winter is the most dangerous season, because doors and windows are kept closed","The OSHA limit for workers is 50 ppm (8-hour average), but in workrooms CO should be close to zero; any level of CO is a sign of inadequate ventilation"]},{heading:"2. Rules for Proper Ventilation",body:"Ventilation required in offices:",points:["When a flueless stove is running, keep a window slightly open to let in fresh air","Rooms with a chimney (flued) stove: do not run an extractor fan at the same time unless a qualified technician has checked that the stove still vents safely; the fan can pull smoke and CO back into the room, even when the fan is in another room","The chimney: must be intact and open, not blocked","Do not block corridors and evacuation routes with stoves","Turn off flueless stoves before sleeping and when you leave the room, and air out the room from time to time","Kitchens and restrooms must have dedicated ventilation"]},{heading:"3. Gas Leak — What Should I Do?",body:"If you smell gas:",points:["Open the windows and doors on your way out, if you can","Do not light any matches and do not touch electrical switches (neither on nor off)!","Do not use a mobile phone inside the building — a spark can cause an explosion","Get out and get everyone else out","Call 115 from outside the building","Only trained, designated staff shut off the gas at the main valve, and only if they can reach it safely without entering the area where the gas has collected; never go back inside to reach it"]},{heading:"4. Monthly Inspection",body:"Inspection:",points:["Check the stove's flue pipe — it must not be blocked","Check gas pipe connections with soap and water (bubble test); never test with a flame","Install a CO detector (Carbon Monoxide Detector)","A qualified technician should inspect the stoves every year","Keep a record of inspections"]}],media:[{kind:"video",src:"media/videos/gov_gas_safety.mp4",title:"Gas Hazards",description:"How to recognize them and what to do"},{kind:"image",src:"media/images/gov_co_detector.png",title:"CO Detector",description:"Where to install it"}],quiz:[{question:"What property does CO (carbon monoxide) have?",options:[{text:"It has a bad smell",correct:!1},{text:"It is red in color",correct:!1},{text:"It is colorless and odorless",correct:!0},{text:"It has no properties",correct:!1}],explanation:"CO is colorless, odorless and tasteless — that is why it is dangerous and a detector is needed."},{question:"If you smell gas, what is the first thing to do?",options:[{text:"Switch on the electric light",correct:!1},{text:"Get out, opening the windows on your way",correct:!0},{text:"Use a mobile phone",correct:!1},{text:"Light the stove",correct:!1}],explanation:"Do not touch flames or switches, open the windows on your way out if you can, get out and call 115 from outside."},{question:"When should a flueless gas stove be turned off?",options:[{text:"Only when the gas runs out",correct:!1},{text:"Before sleeping and when you leave the room",correct:!0},{text:"Only in summer",correct:!1},{text:"It does not need to be turned off",correct:!1}],explanation:"Never leave a flueless stove on while sleeping or when no one is in the room; air out the room from time to time."}]},{id:8,code:"GOV-108",icon:"Lock",accent:"#0891b2",title:"Cybersecurity and Data Protection",subtitle:"Cybersecurity & Data Protection",summary:"Protecting government computer systems and data from cyberattacks and viruses",blocks:[{body:"In the digital age, cyberattacks are a major threat to government offices. Citizens' personal data, official documents and financial systems are all targets. Preparedness and staff training are essential."},{heading:"1. Types of Cyber Threats",body:"Main threats:",points:["Phishing: fake emails and messages that try to steal information","Viruses and malicious software (Malware)","Ransomware: locking data and demanding money","Social engineering: deceiving staff to obtain information","Unsecured WiFi networks: theft of information over the network","Unknown USB flash drives: can transmit viruses"]},{heading:"2. Password Rules",body:"A strong password:",points:["Length: at least 15 characters (NIST SP 800-63B-4)","A long phrase made of several words (Passphrase) is easy to remember and strong","Do not change your password on a fixed schedule; change it only when there is suspicion that it has been exposed","Do not use names, phone numbers or 123456","Enable two-factor authentication (2FA)","Use a different password for each system"]},{heading:"3. Safe Email",body:"How to protect yourself on email:",points:["Do not open unknown links — check the sender's address","Do not open attachments from unknown addresses","If a suspicious email arrives, notify the IT department","Do not send passwords or bank account numbers by email","Use only official email for office business"]},{heading:"4. Physical Security",body:"Protecting devices:",points:["Lock your computer when you step away from your desk (Win+L)","Do not let others view information on your screen","Do not insert unknown USB flash drives into a computer","Destroy confidential papers with a shredder","Protect your work mobile phone with a PIN or fingerprint"]}],media:[{kind:"video",src:"media/videos/gov_cybersecurity.mp4",title:"Cybersecurity",description:"Principles of protection"},{kind:"image",src:"media/images/gov_phishing.png",title:"Recognizing Phishing",description:"Examples of fake emails"}],quiz:[{question:"What is phishing?",options:[{text:"A useful program",correct:!1},{text:"Fake emails used to steal information",correct:!0},{text:"A type of fire",correct:!1},{text:"A backup system",correct:!1}],explanation:"Phishing is fake emails that appear to be official in order to steal information."},{question:"At least how many characters should a strong password have?",options:[{text:"4",correct:!1},{text:"6",correct:!1},{text:"8",correct:!1},{text:"15",correct:!0}],explanation:"NIST (SP 800-63B-4) requires at least 15 characters for a password used without 2FA; length matters more than mixing character types."},{question:"If you find an unknown USB flash drive on the floor, what should you do?",options:[{text:"Insert it into a computer",correct:!1},{text:"Give it to the IT officer",correct:!0},{text:"Take it home",correct:!1},{text:"It makes no difference",correct:!1}],explanation:"Unknown flash drives may contain viruses — give it to the IT department."}]},{id:9,code:"GOV-109",icon:"ShieldAlert",accent:"#7c3aed",title:"Personal Security and Violence Prevention",subtitle:"Personal Safety & Workplace Security",summary:"Protecting staff from security threats and workplace violence",blocks:[{body:"Staff safety is not only about fire and electricity. Workplace violence, threats and security incidents also require preparedness. Every staff member must know how to protect themselves in these situations."},{heading:"1. Security Threats in Offices",body:"Security situations:",points:["Angry and dissatisfied visitors","Physical threats","Suspicious packages and items","Armed attack, theft or looting","Hostage-taking","Threats by telephone or over the internet"]},{heading:"2. Run, Hide, Tell",body:"If a security incident occurs:",points:["Run: if there is a safe route, leave the building quickly","Always know the nearest exit route","Hide: if you cannot run, hide in a room and lock the door","Silence your mobile phone and turn off vibration as well","Tell: once you are in a safe place, call 104 (Police)","Give all information in detail: location, number of people and their description"]},{heading:"3. Dealing with Angry Visitors",body:"De-escalation techniques:",points:["Speak in a calm, low voice","Listen and show that you understand","Keep a safe distance (1.5–2 meters)","Always keep your own exit route clear","Alert a colleague to come and help you","If the situation gets worse, press the panic button or call 104"]},{heading:"4. Office Preparedness",body:"Security preparations:",points:["Install surveillance cameras (CCTV)","An entry control system (Access Control)","A panic button under the reception desks","Staff training every 6 months","Update and test the security plan","Establish a direct line of communication with the nearest police station"]}],media:[{kind:"video",src:"media/videos/gov_security.mp4",title:"Personal Security",description:"Run, Hide, Tell"},{kind:"image",src:"media/images/gov_deescalation.png",title:"De-escalation Techniques",description:"Dealing with angry visitors"}],quiz:[{question:"In the Run, Hide, Tell procedure, what is the first step?",options:[{text:"Hide",correct:!1},{text:"Run",correct:!0},{text:"Fight back",correct:!1},{text:"Call the police",correct:!1}],explanation:"The first action: Run, if there is a safe route."},{question:"When dealing with an angry visitor, what should you do?",options:[{text:"Raise your voice too",correct:!1},{text:"Speak calmly and listen",correct:!0},{text:"Ignore them",correct:!1},{text:"Shut the door on them",correct:!1}],explanation:"Speak calmly and listen — this de-escalates the situation."},{question:"What is the police number in the Kurdistan Region?",options:[{text:"115",correct:!1},{text:"122",correct:!1},{text:"104",correct:!0},{text:"911",correct:!1}],explanation:"104 is the police number in the Kurdistan Region."}]},{id:10,code:"GOV-110",icon:"Armchair",accent:"#16a34a",title:"Workplace Health and Safety",subtitle:"Occupational Health & Ergonomics",summary:"Protecting staff health at work and setting up the desk and chair correctly",blocks:[{body:"Government staff often sit in front of a computer for 8 hours or more. This causes back, eye and shoulder pain. A properly organized workstation (Ergonomics) and physical activity protect the health of employees."},{heading:"1. Setting Up the Desk and Chair (Ergonomics)",body:"A correct workstation:",points:["Chair: it should have back support; adjust the height so that your feet are fully on the floor","Screen: the top of the screen should be at eye level or slightly lower, at a distance of 50–70 cm","Keyboard: elbows at an angle of about 90°","Mouse: close to the keyboard and at the same level","Desk height: must suit your height","Lighting: light should not fall directly on the screen"]},{heading:"2. Protecting the Eyes",body:"Eye strain from screens (Computer Vision Syndrome):",points:["The 20-20-20 rule: every 20 minutes, look at something 20 feet (about 6 meters) away for 20 seconds","Blink often — in front of a screen blinking decreases and the eyes become dry","Reduce screen brightness in the evenings","Enable night mode","Glasses that block blue light have no proven benefit (AAO); if your eyes are dry or tired, see an eye doctor","Have an eye examination every year"]},{heading:"3. Back and Shoulder Pain",body:"Prevention and treatment:",points:["Every 45 minutes, stand up and move around a little","Neck stretch: slowly tilt your head toward each shoulder","Back stretch: slowly rotate your body while seated in the chair","When appropriate, take the stairs instead of the elevator","Drink water regularly throughout the day","Correct sitting posture: back straight, shoulders relaxed, feet on the floor"]},{heading:"4. Mental Health",body:"The psychological well-being of staff:",points:["Work stress: identify the main causes","Time management: keep work time and break time separate","Talking: talk with your colleagues about problems","Take a 15-minute break outdoors every day","Do not use your mobile phone for work during breaks","If symptoms persist: contact a mental health professional"]}],media:[{kind:"video",src:"media/videos/gov_ergonomics.mp4",title:"Ergonomics",description:"Setting up the desk and chair"},{kind:"image",src:"media/images/gov_posture.png",title:"Correct Sitting Posture",description:"An instructional image"},{kind:"image",src:"media/images/gov_eye_care.png",title:"The 20-20-20 Rule",description:"Protecting the eyes"}],quiz:[{question:"What is the 20-20-20 rule for?",options:[{text:"Protecting the ears",correct:!1},{text:"Protecting the eyes",correct:!0},{text:"Protecting the back",correct:!1},{text:"Protecting the hands",correct:!1}],explanation:"Every 20 minutes, look at something 20 feet (about 6 meters) away for 20 seconds — to protect the eyes (AAO)."},{question:"How far from the eyes should a computer screen be?",options:[{text:"20–30 cm",correct:!1},{text:"30–40 cm",correct:!1},{text:"50–70 cm",correct:!0},{text:"1 meter",correct:!1}],explanation:"A distance of 50–70 cm (about an arm's length) is most suitable."},{question:"How often should staff get up from their desk and move around?",options:[{text:"Every 20 minutes",correct:!1},{text:"Every 45 minutes",correct:!0},{text:"Every 2 hours",correct:!1},{text:"Every 1 hour",correct:!1}],explanation:"It is recommended to get up and move around a little every 45 minutes."}]},{id:11,code:"GOV-111",icon:"Waves",accent:"#2563eb",title:"Floods and Water Damage",subtitle:"Flood Response & Water Damage",summary:"Preparing for and responding to floods and water damage in offices",blocks:[{body:"Water can reach offices from several sources: rain and natural floods, burst water pipes, air-conditioning system problems, or water leaking from the floor above. Preparedness and awareness reduce the damage."},{heading:"1. Sources of Water in Offices",body:"Where water comes from:",points:["Rain and natural floods: especially in low-lying areas","Burst water pipes: old and corroded pipes","Melting snow: snow turns into water and enters the building","Water leaking from the floor above: from restrooms and kitchens","Air-conditioning system: accumulated water and leaks","Water tanks: a tank bursting or leaking"]},{heading:"2. Before a Flood — Preparedness",body:"Required preparations:",points:["Keep important documents on upper floors and in high cabinets","Do not place computers on the floor — keep them at least 30 cm above the floor","Electrical cables should not lie on the floor","Know the plumbing layout and the location of the main water valve","Have a water drainage pump (Sump Pump) ready","Keep a list of technical and emergency numbers ready"]},{heading:"3. During a Flood",body:"If water enters the office:",points:["If you are not standing in water and can reach the switch safely, cut off the main power — electricity and water together are deadly","Call 115 and notify the building manager","All staff should move safely to higher ground","If the water is shallow: move documents and computers to a higher location","Do not enter flood water: 15 cm of fast-moving water can knock a person down and 30 cm can carry a car away; there is also a risk of electrocution and disease","Shut off the main water valve"]},{heading:"4. After a Flood",body:"After the water recedes:",points:["Building inspection: before returning, a building expert should inspect the building","Do not switch the power on until a technician confirms that it is safe","Disinfection: flood water is contaminated and carries bacteria and diseases","Ventilation: open all windows and doors","Take photos for records and insurance","Remove damaged items safely"]}],media:[{kind:"video",src:"media/videos/gov_flood_response.mp4",title:"Flood Response",description:"What to do when water comes in"},{kind:"image",src:"media/images/gov_flood_prep.png",title:"Flood Preparedness",description:"Step by step"}],quiz:[{question:"During a flood in the office, what is the first thing to do?",options:[{text:"Gather the documents",correct:!1},{text:"Cut off the main power (if it is safe)",correct:!0},{text:"Take photos",correct:!1},{text:"Talk on the phone",correct:!1}],explanation:"Electricity and water together create a risk of death. If you are not standing in water and can reach the switch safely, cut off the main power immediately; if not, get out and call 115."},{question:"Where should important documents be kept in an office at risk of flooding?",options:[{text:"On the floor",correct:!1},{text:"In the basement",correct:!1},{text:"On upper floors and in high cabinets",correct:!0},{text:"It makes no difference",correct:!1}],explanation:"Always keep important documents in a high and safe location."},{question:"Why is disinfection necessary after a flood?",options:[{text:"For a pleasant smell",correct:!1},{text:"Flood water carries bacteria and diseases",correct:!0},{text:"For appearance",correct:!1},{text:"It is not necessary",correct:!1}],explanation:"Flood water is highly contaminated and carries bacteria and diseases."}]},{id:12,code:"GOV-112",icon:"FlaskConical",accent:"#65a30d",title:"Chemicals and Cleaning Agents",subtitle:"Chemical Safety & Cleaning Agents",summary:"Safe use of cleaning agents and chemicals in offices",blocks:[{body:"Government offices use many types of cleaning agents. Mixing some of these substances can produce toxic and dangerous gases. Knowing the substances and using them correctly saves lives."},{heading:"1. Hazardous Substances in Offices",body:"These substances are found in many offices:",points:["Chlorine bleach: for cleaning restrooms — if mixed with acid or ammonia, it produces toxic gases","Ammonia: for cleaning windows — harmful to breathing","Acid: for removing limescale — burns the skin","Printer toner: a fine powder — a hazard to the lungs","Correction fluid: flammable, and its vapors are harmful","Battery acid: chemical burns"]},{heading:"2. The Never-Mix Rule!",body:"Never mix these substances:",points:["Bleach + ammonia = chloramine gas (toxic and deadly)","Bleach + acid = chlorine gas (toxic and deadly)","Bleach + vinegar (which is an acid) = chlorine gas","Use each substance on its own","Dilute only with water, following the instructions on the container — not with another substance","Always read the instructions on the container (label)"]},{heading:"3. Personal Protective Equipment (PPE)",body:"Protective equipment when using chemicals:",points:["Gloves: required for all chemicals","Mask: when using bleach and strong-smelling substances","Safety goggles: for acids and sprays","Protective clothing: for strong substances","If a substance gets on the skin or in the eyes: rinse with running water for at least 20 minutes; if there is a burn or poisoning, call 122","Ventilation: open the windows while cleaning"]},{heading:"4. Storing and Disposing of Chemicals",body:"Rules for storing chemicals:",points:["Keep them in a locked location","Away from sunlight and heat","Write the name of the substance on all bottles and containers","Keep Safety Data Sheets (SDS) available","Dispose of expired substances properly — do not pour them down the drain","Keep them away from food and drinking water"]}],media:[{kind:"video",src:"media/videos/gov_chemical_safety.mp4",title:"Chemical Safety",description:"Correct use"},{kind:"image",src:"media/images/gov_mixing_danger.png",title:"The Danger of Mixing",description:"Which substances must not be mixed"},{kind:"image",src:"media/images/gov_ppe_cleaning.png",title:"PPE for Cleaning",description:"Protective equipment"}],quiz:[{question:"What happens if we mix bleach and ammonia?",options:[{text:"It makes a better cleaner",correct:!1},{text:"It produces chloramine gas (toxic)",correct:!0},{text:"Nothing happens",correct:!1},{text:"It produces a pleasant smell",correct:!1}],explanation:"Mixing bleach and ammonia produces chloramine gas — there is a risk of death."},{question:"If a chemical gets on the skin, what should we do?",options:[{text:"Wipe it off with a tissue",correct:!1},{text:"Rinse with water for at least 20 minutes",correct:!0},{text:"Apply cream to it",correct:!1},{text:"Do nothing",correct:!1}],explanation:"Immediately rinse with running water for at least 20 minutes and remove contaminated clothing; if there is a burn, call 122."},{question:"Where should cleaning agents be kept in the office?",options:[{text:"On the desk",correct:!1},{text:"Near food",correct:!1},{text:"In a locked location, away from heat",correct:!0},{text:"It makes no difference",correct:!1}],explanation:"Keep them in a locked location, away from heat and food."}]},{id:13,code:"GOV-113",icon:"ArrowUpDown",accent:"#4f46e5",title:"Elevator and Stairway Safety",subtitle:"Elevator & Stairway Safety",summary:"Using elevators safely and preventing falls on stairs",blocks:[{body:"Elevators and stairways are common locations of incidents in government buildings. Falls on stairs are among the most common workplace incidents, and being trapped in an elevator is a serious situation. Knowing the rules reduces the risk."},{heading:"1. Elevator Safety",body:"Rules for using the elevator:",points:["If the elevator is slow to arrive, be patient — do not press the button repeatedly","Do not open the elevator door by hand — let it open by itself","Do not load more than the permitted capacity (as written on the elevator)","Do not use it during a power outage","Do not use it during a fire or an earthquake — use the stairs only","Know where the emergency button is"]},{heading:"2. Being Trapped in an Elevator",body:"If you are trapped in an elevator:",points:["Stay calm — do not panic","Press the emergency button","Use the telephone inside the elevator","If there is mobile phone coverage, call 115","Do not try to open the door or climb out — it is dangerous","Wait until the technician or the 115 team arrives — the air inside the elevator will not run out"]},{heading:"3. Stairway Safety",body:"Preventing falls on stairs:",points:["Always hold the handrail","Watch where you are stepping — do not use your mobile phone","One step at a time — do not jump","Walk carefully on wet stairs","When carrying a load, keep one hand free to hold the handrail","Stairway lighting must be good — replace burned-out bulbs"]},{heading:"4. Inspection and Maintenance",body:"Regular inspections:",points:["Elevators: monthly maintenance by a qualified company and annual inspection by an approved authority","Post the inspection certificate inside the elevator","Check the emergency lighting of the stairways","Repair broken stairs immediately","Place warning signs at slippery spots","Keep stairs clear — do not leave any items on the stairs"]}],media:[{kind:"video",src:"media/videos/gov_elevator_safety.mp4",title:"Elevator Safety",description:"Correct use and being trapped inside"},{kind:"image",src:"media/images/gov_stair_safety.png",title:"Stairway Safety",description:"Rules for preventing falls"}],quiz:[{question:"During a fire, what should we use to get out?",options:[{text:"The elevator",correct:!1},{text:"The building's stairs",correct:!0},{text:"It makes no difference",correct:!1},{text:"The windows",correct:!1}],explanation:"Never use the elevator during a fire or an earthquake — exit by the stairs only."},{question:"If you are trapped in an elevator, what should you do?",options:[{text:"Try to open the door",correct:!1},{text:"Scream in panic",correct:!1},{text:"Press the emergency button and stay calm",correct:!0},{text:"Jump",correct:!1}],explanation:"Stay calm and press the emergency button. Do not try to open the door."},{question:"To prevent falls on stairs, what should we do?",options:[{text:"Jump",correct:!1},{text:"Use a mobile phone",correct:!1},{text:"Hold the handrail and watch where you are stepping",correct:!0},{text:"Close your eyes",correct:!1}],explanation:"Always hold the handrail and watch where you are stepping."}]},{id:14,code:"GOV-114",icon:"Network",accent:"#e11d48",title:"Crisis Management",subtitle:"Crisis Management & ICS",summary:"Establishing a crisis management team and the Incident Command System (ICS)",blocks:[{body:"Every government office must have a Crisis Management Team. A crisis can be a fire, an earthquake, a flood, a security attack or even a cyberattack. The Incident Command System (ICS) is an international tool for managing any incident."},{heading:"1. The Crisis Management Team (CMT)",body:"Team composition:",points:["Team leader (Crisis Commander): makes decisions and gives direction","Operations officer: organizes activities","Communications officer: liaison with external parties and the media","Logistics officer: supplies and equipment","Records officer: documents the incidents","First aid officer: assists the injured"]},{heading:"2. The Incident Command System (ICS)",body:"ICS (Incident Command System):",points:["Developed in the United States and now used in many countries","One incident commander — the chain of command is clear","Assignment of roles: everyone knows their role and reports to one supervisor","Unified communication: one communication channel and plain language","Flexible organization (Modular): the organization expands or contracts according to the size of the incident","Reporting: reports are updated at set times"]},{heading:"3. Crisis Response Steps",body:"General procedure:",points:["1. Alert: activate the alarm system","2. Assessment: find out what has happened and how large it is","3. Activation: convene the CMT","4. Management: make decisions and carry them out","5. Communication: inform all parties","6. Recovery: carry out the plan for returning to normal operations"]},{heading:"4. Training and Testing",body:"Ongoing preparedness:",points:["A tabletop exercise every 3 months","A full-scale drill every 6 months","Update the crisis plan every year","Test the communication system","Cooperation with Civil Defense (115) and the Police (104)","After every exercise, conduct an evaluation and improve the work"]}],media:[{kind:"video",src:"media/videos/gov_crisis_management.mp4",title:"Crisis Management",description:"The ICS system and the CMT"},{kind:"image",src:"media/images/gov_ics_chart.png",title:"ICS Chart",description:"The command structure"}],quiz:[{question:"In the ICS system, how many incident commanders are there?",options:[{text:"3",correct:!1},{text:"5",correct:!1},{text:"1 (one)",correct:!0},{text:"10",correct:!1}],explanation:"In ICS there is one incident commander, so that the chain of command is clear. If several agencies are involved, a Unified Command works under a single plan."},{question:"According to this program, how often is a tabletop exercise required?",options:[{text:"Every year",correct:!1},{text:"Every 6 months",correct:!1},{text:"Every 3 months",correct:!0},{text:"Only once",correct:!1}],explanation:"This program recommends conducting a tabletop exercise every 3 months."},{question:"What is the first step in responding to a crisis?",options:[{text:"Management",correct:!1},{text:"Communication",correct:!1},{text:"Alerting and activating the alarm system",correct:!0},{text:"Recovery",correct:!1}],explanation:"The first step: alert — activate the alarm system."}]},{id:15,code:"GOV-115",icon:"Megaphone",accent:"#c026d3",title:"Emergency Communication",subtitle:"Emergency Communication",summary:"The communication and alerting system during incidents",blocks:[{body:"During incidents, accurate and rapid communication saves lives. In many incidents, the lack of good communication has increased the number of casualties. Every government office must have a robust communication system."},{heading:"1. Alerting Systems",body:"There are several systems:",points:["Internal siren: the fire and emergency alarm","Public address system (PA System): for sending messages to all floors","Mobile text messages (SMS Group): for staff","Urgent email: for official notifications","WhatsApp and Telegram groups: for rapid coordination","Two-way radio (Walkie-Talkie): for the emergency team"]},{heading:"2. The Communication Chain",body:"Who sends the message:",points:["1. The reporter: the person who saw the incident — calls 115 immediately (and 122 if there are injured people)","2. Floor warden: the staff member responsible for the floor and its rooms","3. Crisis commander: makes decisions and gives direction","4. Communications officer: liaison with 115 and external parties","5. Office director: informs the higher level","All messages must be precise and contain complete information"]},{heading:"3. Content of an Emergency Message",body:"A good message contains:",points:["Location: where it happened (building, floor, room)","What: what happened (fire, earthquake, attack...)","People: how many people are injured or trapped","Hazard: is there an ongoing hazard?","Needs: what help is needed","Contact: your phone number for follow-up"]},{heading:"4. Communicating with External Parties",body:"Contact with external parties:",points:["115 — Civil Defense: fire and rescue","122 — Ambulance: injuries and illness","104 — Police: security situations","Media: only the communications officer speaks","Staff families: notified by the simplest means","General directorate: the official report"]},{heading:"5. Testing the System",body:"Ongoing checks:",points:["Test the internal siren every month","Send a test message to the group every week","Check the batteries and range of the two-way radios","Update the list of emergency numbers","Evaluate the communication system after every drill","Backup plan: if a system fails, what replaces it?"]}],media:[{kind:"video",src:"media/videos/gov_emergency_comm.mp4",title:"Emergency Communication",description:"The communication system and its chain"},{kind:"image",src:"media/images/gov_comm_chain.png",title:"The Communication Chain",description:"Who contacts whom"},{kind:"image",src:"media/images/gov_message_template.png",title:"Sample Message",description:"The content of a correct message"}],quiz:[{question:"In an emergency, which system is fastest for alerting all floors?",options:[{text:"Email",correct:!1},{text:"WhatsApp",correct:!1},{text:"Public address system (PA)",correct:!0},{text:"A paper letter",correct:!1}],explanation:"The PA system is the fastest because it is heard immediately on all floors."},{question:"What information should an emergency message contain?",options:[{text:"Only the location",correct:!1},{text:"Only the number of injured",correct:!1},{text:"Location, what happened, people, hazard, needs",correct:!0},{text:"Only the number 115",correct:!1}],explanation:"A complete message: location + what happened + people + hazard + needs + contact number."},{question:"During a crisis, who is authorized to speak to the media?",options:[{text:"Any staff member",correct:!1},{text:"Only the communications officer",correct:!0},{text:"Visitors",correct:!1},{text:"Only the police",correct:!1}],explanation:"Only the communications officer is authorized to speak to the media, so that incorrect information is not spread."}]},{id:16,code:"GOV-116",icon:"Heart",accent:"#db2777",title:"First Aid and CPR",subtitle:"First Aid & CPR — Complete Training",summary:"Complete training in first aid, CPR and emergency response in offices",blocks:[{body:"First aid is the initial help given to an injured or ill person before medical teams arrive. In offices there is a risk of fire, earthquakes and sudden illness. Every staff member must know how to perform CPR, stop bleeding and protect an injured person until the ambulance (122) arrives."},{heading:"1. CPR — Cardiopulmonary Resuscitation",body:"CPR is a life-saving procedure used when a person's heart or breathing stops:",points:["1. Scene safety: is the scene safe? (Is it free of live electricity, fire and gas?)",'2. Responsiveness: gently shake their shoulders and ask in a loud voice: "Are you all right? Can you hear me?"',"3. Call 122: if they do not respond and are not breathing normally, call 122 immediately and get an AED or ask someone to bring one","4. Chest compressions: 30 compressions in the center of the chest — depth 5–6 cm, rate 100–120 compressions per minute","5. Breaths: tilt the head back and lift the chin, pinch the nose and give 2 breaths of 1 second each; if you have not been trained, give chest compressions only","6. Continue (30:2): until the ambulance team (122) arrives","7. AED: if one is available, switch it on, place the pads on the bare chest and follow the voice prompts"]},{heading:"2. Stopping Bleeding",body:"Severe bleeding can quickly lead to death:",points:["Direct pressure: place a clean cloth on the wound and press firmly without stopping; if the cloth becomes soaked with blood, do not remove it — place another one on top","Wound packing: if the wound is deep (such as in the thigh, armpit or neck), pack clean gauze into the wound and press firmly","Tourniquet: use it early for life-threatening bleeding from an arm or leg, 5–7 cm above the wound; write down the time it was applied and never loosen it","Embedded object: if metal or glass is lodged in the wound — do not remove it! Stabilize it in place and call 122"]},{heading:"3. Treating Burns",body:"Burns in offices are caused by heat, chemicals and electricity:",points:["Thermal burns: run cool water over the burn for 20 minutes (not ice!)","Chemical burns: rinse with plenty of running water for 20 minutes","Electrical burns: first cut off the power! Then cool it like a thermal burn and call 122","Do not burst burn blisters; do not use oil, ointment or toothpaste"]},{heading:"4. Fractures and Spinal Injuries",body:"After a fall:",points:["Splinting: do not move the injured limb — immobilize it with a piece of wood or cardboard","Protecting the spine: if a person has fallen from a height, do not move them — keep them still and call 122. Move them only if the place is unsafe (fire, traffic, collapse, gas, rising water), keeping the head, neck and back in line; if they need CPR, lay them on their back on a firm surface. Do not put them on their side (recovery position)","Cooling: wrap ice in a piece of cloth and place it on the painful area (not directly on the skin)"]},{heading:"5. Electric Shock",body:"Electricity can stop the heart:",points:["Cut off the power immediately! Do not touch the casualty until the power is off","If you cannot cut off the power and it is the building's normal supply (low voltage): move the cable away from the person with a dry wooden or plastic object; with high voltage, stay away and call 115","Everyone who has received an electric shock must go to the hospital — call 122; if they are not breathing, start CPR"]}],media:[{kind:"video",src:"media/videos/gov_cpr.mp4",title:"CPR and First Aid",description:"CPR training for staff"}],quiz:[{question:"In CPR, how many chest compressions should be given per minute?",options:[{text:"50–70",correct:!1},{text:"80–90",correct:!1},{text:"100–120",correct:!0},{text:"150+",correct:!1}],explanation:"There should be 100–120 compressions per minute (AHA 2025)."},{question:"If a sharp object is lodged in a wound, what do you do?",options:[{text:"I pull it out",correct:!1},{text:"I leave it in place and call 122",correct:!0},{text:"I step back and do nothing",correct:!1},{text:"I wash it with water",correct:!1}],explanation:"Removing the object will increase the bleeding; stabilize it in place and call 122."},{question:"If a person has received an electric shock, what is the first thing to do?",options:[{text:"I grab their hand",correct:!1},{text:"I perform CPR",correct:!1},{text:"I cut off the power",correct:!0},{text:"I pour water on them",correct:!1}],explanation:"The power must be cut off first, so that you do not become a casualty yourself."}]},{id:17,code:"GOV-117",icon:"FlameKindling",accent:"#dc2626",title:"Classification of Fire Types",subtitle:"Fire Classification — NFPA 10 / BS EN 2",summary:"The international classification of fire types and choosing the right fire extinguisher",blocks:[{body:"Fire classification is the foundation of Civil Defense work. NFPA 10 (the American standard) and EN 2 (the European standard) are the two main systems, and we must always state which system is meant. Classes here use NFPA 10 letters as the project reference; the official system for Duhok is not yet confirmed. EN 2 equivalents: NFPA A = EN A; NFPA B (liquids) = EN B; NFPA B (gases) = EN C; NFPA C (live electrical equipment) has no EN class; NFPA D = EN D; NFPA K = EN F. Choosing the wrong fire extinguisher can make a fire bigger or cause injuries. This lesson explains each class according to international standards."},{heading:"1. Class A — Ordinary Solid Materials (Solid Combustibles)",body:"Organic solid materials that leave ash behind:",points:["Fuel: wood, paper, cloth, plastic, rubber, trash","Auto-ignition temperature: paper about 218–246°C","Characteristics: leaves ash and embers behind, and the fire can persist deep inside the material","Fire extinguishers: water, ABC powder, foam — read the label and its class symbols (color is not the fire class)","In offices: most combustible materials are paper, files and room furnishings","Standard: NFPA 10, EN 2","Technique: use an extinguisher only if all of this is true: the fire is small and just starting, the extinguisher is the right type, your exit is behind you, the alarm has been raised and 115 called, you are trained, and no smoke or heat blocks your way out. Then PASS: start from the distance shown on the extinguisher label and aim the nozzle at the base of the fire; if the fire does not go out at once, get out and close the door"]},{heading:"2. Class B — Flammable Liquids",body:"Liquids that give off flammable vapors at normal temperatures (in NFPA, flammable gases are also included):",points:["Fuel: gasoline, diesel, kerosene, alcohol, thinner, paint","Flash point (depends on the exact fuel): gasoline about −43°C, diesel about 52–96°C","Characteristics: the vapor of the liquid burns, not the liquid itself","Fire extinguishers for liquids: foam, CO₂ or ABC powder; for alcohol and other polar solvents: CO₂, ABC powder or alcohol-resistant (AR) foam, because ordinary foam breaks down on them. Gas fire (LPG, natural gas): the priority is to stop the gas; a qualified person closes the gas valve only if it is safe to reach. Do not put out a gas flame if the gas cannot be stopped safely: unburned gas can build up and explode. If it is not safe, get everyone out, raise the alarm and call 115. Foam is not the general choice for gas fires","Do not spray water from a hose onto a burning liquid: it splashes and spreads the burning liquid (Slop-over / Boil-over). BLEVE is something different: it is the explosion of a pressurized container after it has been heated, and cooling the container with water from a distance can help prevent it; this is a task for the 115 team, and everyone else evacuates","In offices: fuel storage for generators and service vehicles","Standard: NFPA 30 (Flammable and Combustible Liquids Code)","Method: cut off the oxygen (smothering), not just cooling"]},{heading:"3. Class C in NFPA — Energized Electrical Equipment",body:"Fires in electrical equipment while it is energized:",points:["Fuel: computers, servers, outlets, electrical panels","Arc flash temperature: reaches about 19,400°C (35,000°F) — about 4 times hotter than the surface of the sun (OSHA)","Fire extinguishers: CO₂, ABC powder, clean agents such as FK-5-1-12","Do not use water or foam on live electrical equipment unless the label shows a Class C rating or an electrical-test marking (some water-mist units) — risk of fatal electric shock","First, if it is safe to reach without passing the fire, switch off the power at the panel; then treat the fire by the burning material","Standard: NFPA 70E (Electrical Safety in the Workplace)","In ICT rooms: clean agents are best — they do not damage valuable equipment","Note: in EN 2, Class C is gases, not electricity; in Europe electrical fires are not a separate class, and Class E (electrical) is used only in Australia"]},{heading:"4. Class D — Combustible Metals",body:"Combustible metals — one of the most dangerous types:",points:["Fuel: magnesium, titanium, sodium, potassium, lithium metal","Temperature: magnesium burns at about 3,100°C (5,610°F)","Never water! Water + magnesium = hydrogen and explosion","Never CO₂! Magnesium burns even in CO₂ and the fire intensifies","Only: an extinguisher or agent whose label lists that metal (Class D powders such as sodium chloride or graphite powder); the agent differs from metal to metal (lithium, for example, needs an agent listed for lithium). Never ordinary powder or foam. Dry sand only if the site fire plan or the metal's safety data sheet names it and it is completely dry","In offices: chemical laboratories and metalworking areas. Ordinary lithium-ion batteries contain no lithium metal, and cooling with water is recommended for them","Standard: NFPA 484 (Combustible Metals)","Call 115 immediately — a specialized team is required"]},{heading:"5. Class F (EN 2) / Class K (NFPA) — Cooking Oils",body:"Cooking oils and fats — one of the most common kitchen fires:",points:["Fuel: cooking oils (vegetable and animal) and fats","Auto-ignition temperature: generally above 340°C, depending on the oil","Extinguisher: wet chemical (potassium salts) — made for cooking oils and fats; many are also rated for Class A, so read the label and use it as the label shows (in the UK it has a yellow band, BS 7863)","Never water! Water in hot oil turns to steam instantly and violently throws out the burning oil (a fireball)","ABC powder is not suitable for cooking oil — the fire can reignite","Method: if the fire is small, turn off the heat, cover it with a lid or a fire blanket and do not remove it","In the office cafeteria: a Wet Chemical fire extinguisher near the cooking area (NFPA 10: no more than 9 meters away)","Standard: BS EN 3-7, NFPA 10, NFPA 17A (Wet Chemical Systems)"]},{heading:"6. Choosing the Right Fire Extinguisher — Decision Matrix",body:"Basis: 1) the burning material, 2) the size of the fire, 3) the location:",points:["Matrix: A: water or ABC | B liquids: foam, CO₂ or ABC (polar solvents: AR foam, CO₂ or ABC) | B gas: stop the gas first if it is safe; never put out a gas flame you cannot stop | C: CO₂, Clean Agent or ABC powder (powder damages electronics) | D: a Class D extinguisher listed for that metal | F/K: Wet Chemical","Size: use a fire extinguisher only on a small fire that is just starting; do not use it if the fire is bigger than a wastebasket, is spreading, or smoke is building up: get out and call 115","Location: ICT rooms: Clean Agent or CO₂ | paper storerooms: water or ABC | cafeteria: Wet Chemical","For a typical office: ABC and CO₂, plus Wet Chemical in the kitchen","Discharge time: small extinguishers empty quickly, often in a few seconds, and the exact discharge time is on the label — be within the range shown on the label, with your exit behind you, before you start","Inspection and service (NFPA 10 and OSHA; the rules for Duhok are not yet confirmed): visual check monthly; inspection and maintenance yearly by a qualified technician; recharge after any use; stored-pressure dry chemical: emptied and checked inside every 6 years; hydrostatic test every 5 years for water, foam, CO₂, Wet Chemical and stainless-steel dry chemical, every 12 years for stored-pressure dry chemical with mild steel, brazed brass or aluminum shells"]},{heading:"7. Stages of Fire Development",body:"Every fire goes through 4 stages:",points:["1. Incipient: little smoke and a small fire","2. Growth: the heat increases and the fire spreads","3. Fully developed: all materials in the room are burning and the temperature can exceed 1,000°C","4. Decay: the fuel decreases, but there is a risk of Backdraft","Flashover between stages 2 and 3: when the temperature of the upper gas layer reaches about 500–600°C, all materials in the room ignite rapidly","Backdraft: opening a door to a room that has fire inside and little oxygen supplies it with oxygen, and a fire explosion occurs","Staff response: extinguishing a fire is safe only at stage 1 (Incipient)"]}],media:[{kind:"video",src:"media/videos/gov_fire_classes.mp4",title:"Classification of Fire Types",description:"Showing the fire classes according to NFPA and EN 2"},{kind:"image",src:"media/images/gov_fire_decision.png",title:"Decision Matrix",description:"Choosing the right fire extinguisher"}],quiz:[{question:"A computer fire (Class C in NFPA) is extinguished with which fire extinguisher?",options:[{text:"Water",correct:!1},{text:"CO₂ or Clean Agent",correct:!0},{text:"Foam",correct:!1},{text:"Class D extinguisher",correct:!1}],explanation:"CO₂ or Clean Agent — they leave no residue. ABC powder also works but damages electronics. Ordinary water and foam conduct electricity and can cause electric shock."},{question:"What is Class D?",options:[{text:"Liquids",correct:!1},{text:"Wood and paper",correct:!1},{text:"Combustible metals",correct:!0},{text:"Gases",correct:!1}],explanation:"Class D = combustible metals (magnesium, titanium...). Only an extinguisher or agent whose label lists that metal; dry sand only if the site fire plan or the metal's safety data sheet names it and it is completely dry."},{question:"Why must water not be used on a cooking oil fire?",options:[{text:"It does not work",correct:!1},{text:"The water turns to steam and violently throws out the burning oil",correct:!0},{text:"It is too heavy",correct:!1},{text:"Oil never catches fire",correct:!1}],explanation:"Very hot oil instantly turns water into steam; the steam throws out the burning oil and creates a fireball."},{question:"What is NFPA 10 the standard for?",options:[{text:"Classification of employees",correct:!1},{text:"Portable fire extinguishers",correct:!0},{text:"Water sprinkler systems",correct:!1},{text:"Data protection",correct:!1}],explanation:"NFPA 10 is the American standard for portable fire extinguishers: selection, installation, inspection and maintenance."},{question:"Which stage of fire is the only stage at which a staff member can safely extinguish the fire?",options:[{text:"Decay",correct:!1},{text:"Fully Developed",correct:!1},{text:"Incipient",correct:!0},{text:"Flashover",correct:!1}],explanation:"Extinguishing a fire by staff is safe only at the initial stage (Incipient)."},{question:"At about what temperature of the upper gas layer does flashover generally occur?",options:[{text:"200°C",correct:!1},{text:"400°C",correct:!1},{text:"About 500–600°C",correct:!0},{text:"900°C",correct:!1}],explanation:"Flashover occurs when the temperature of the upper gas layer reaches about 500–600°C — all materials in the room ignite rapidly."}]},{id:18,code:"GOV-118",icon:"FireExtinguisher",accent:"#ea580c",title:"Fire Extinguishers — Types and Selection",subtitle:"Fire Extinguisher Types — NFPA 10 + BS EN 3",summary:"The six main types of portable fire extinguishers according to international standards and how to choose them for offices",blocks:[{body:"A fire extinguisher in an office must be chosen according to the type of fire that could occur. For most offices, ABC powder and CO₂ together are the basis, plus Wet Chemical in the kitchen. This lesson explains the six main types, their colors, sizes, the PASS technique and the inspection schedule. Classes here use NFPA 10 letters as the project reference; the official system for Duhok is not yet confirmed. EN 2 equivalents: NFPA A = EN A; NFPA B (liquids) = EN B; NFPA B (gases) = EN C; NFPA C (live electrical equipment) has no EN class; NFPA D = EN D; NFPA K = EN F. Color is not the fire class: the colors below are the UK practice (BS EN 3 red body with a BS 7863 colored band); the color practice in Duhok is not yet confirmed, so always read the label and its class symbols."},{heading:"1. Water Fire Extinguisher (Class A)",body:"The most common fire extinguisher for Class A — solid materials:",points:["Color in the UK (BS EN 3): all red, no band","Class: A only (wood, paper, cloth, plastic)","How it works: it cools the fire and reduces the heat","Common sizes: 6 and 9 liters","Distance: start from the distance shown on the extinguisher label, with your exit behind you, and move closer only as the fire gets smaller","Never use it on electricity (shock), liquids or cooking oil (it spreads the fire)","In the office: corridors and archive rooms","It is inexpensive, but suitable only for Class A","Inspection: monthly visual check (pressure gauge if there is one, pin and seal) and yearly inspection and maintenance by a qualified person"]},{heading:"2. Foam Fire Extinguisher (Classes A and B)",body:"AFFF foam (Aqueous Film-Forming Foam):",points:["Color in the UK (BS EN 3 / BS 7863): red with a cream band","Class: A and B (flammable liquids) — not for alcohol or other polar solvents unless it is alcohol-resistant (AR) foam, and not the general choice for gas fires","How it works: the foam forms a layer on top of the liquid, cuts off the oxygen and cools","Common sizes: 6 and 9 liters","Distance: start from the distance shown on the label and move closer only as the fire gets smaller","Suitable for: fuel storage areas and generator locations","Do not use it on energized electrical equipment — like water, it conducts electricity","In the office: the vehicle parking area and the diesel storage","AFFF contains PFAS substances that harm the environment and health; fluorine-free foam is the new replacement"]},{heading:"3. CO₂ (Carbon Dioxide) Fire Extinguisher (Class B and Electrical Fires)",body:"Best for electrical equipment and liquids:",points:["Color in the UK (BS EN 3 / BS 7863): red with a black band","Class: B and live electrical equipment (NFPA B and C; under EN 2, C means gas and CO₂ is not rated for gas fires)","How it works: CO₂ gas displaces the oxygen around the fire (smothering)","Common sizes: 2 and 5 kg","Distance: CO₂ has a short range; start from the distance shown on the label and move closer only as the fire gets smaller","Suitable for: ICT rooms, electrical panels, the server room","It leaves no residue and does not damage valuable equipment; but it is not good for deep-seated Class A fires","Hazard: in enclosed rooms it reduces the oxygen — after use, evacuate the room and ventilate it","Its horn becomes extremely cold (about −78°C) — do not touch the horn, hold only the handle","In the office: the ICT department, the server room and near electrical panels"]},{heading:"4. ABC Dry Chemical Powder Fire Extinguisher",body:"The most common fire extinguisher — for Classes A, B and C, not for D and K/F:",points:["Color in the UK (BS EN 3 / BS 7863): red with a blue band","Class: A, B and C — not D (metals) and not K/F (cooking oil)","Agent: monoammonium phosphate","How it works: the powder stops the chemical reaction of the fire","Common sizes: 1, 2, 6 and 9 kg","Distance: start from the distance shown on the label and move closer only as the fire gets smaller","Suitable for: corridors, garages and storerooms — not for cooking oil","The powder spreads through the room, reduces visibility and is difficult to clean up","The powder damages electronic equipment — for computers and ICT, CO₂ is better","In the office: corridors, garages and near exits","It is inexpensive and is commonly installed in offices"]},{heading:"5. Wet Chemical Fire Extinguisher (Class F/K) — Kitchen",body:"Designed specifically for hot cooking oils and fats:",points:["Color in the UK (BS EN 3 / BS 7863): red with a yellow band","Class: K (NFPA) / F (EN 2) — cooking oil","Agent: potassium salts (potassium acetate or potassium citrate)","How it works: it turns the oil into a soap-like layer (Saponification) that cools the oil and cuts off the oxygen","Common sizes: 2 and 6 liters","Use it as the label shows: apply it gently onto the oil with the long applicator so that the oil does not splash","Made for cooking oils and fats (NFPA K / EN F); many are also rated for Class A, so read the label. Not for diesel or kerosene (Class B)","Never put water on hot oil — the water turns to steam and throws out the burning oil!","In the office: the cafeteria and kitchen","Before use, if it is safe, cut off the gas or electricity to the cooking appliance"]},{heading:"6. Clean Agent Fire Extinguishers (FK-5-1-12 / HFC-227ea)",body:"For ICT and valuable equipment:",points:["Color: red body with the name of the agent written on it (a green label in some countries)","Class: the rating depends on the model; read the label","Agent: FK-5-1-12 (trade name Novec 1230) or HFC-227ea","How it works: a clean gas — it leaves no residue and does not damage equipment","Fixed clean agent systems (NFPA 2001), which are not portable extinguishers, discharge in 10 seconds or less","Suitable for: the server room, data center, archives","Portable clean agent extinguisher: the class rating and minimum room size are on the label; leave the room after use. Fixed systems: at design concentrations the agent is safe for people, but the room must be evacuated because of the smoke and products of combustion","It does not damage the ozone layer and has replaced Halon 1301","It is expensive; in server rooms it is often installed as a fixed total flooding system, which is separate from portable extinguishers","In the office: only in sensitive areas — the server room and the Emergency Operations Center (EOC)","Standard: NFPA 2001 (Clean Agent Fire Extinguishing Systems)"]},{heading:"7. PASS — How to Use a Fire Extinguisher",body:`Before you use an extinguisher (every answer must be yes):
• The fire is small and just starting, like a fire in a wastebasket or a pan.
• The extinguisher is the right type for this fire.
• Your exit is behind you and the fire is not between you and the exit.
• The alarm has been raised: others are warned and 115 has been called.
• You are trained to use the extinguisher.
• No smoke or heat is blocking your way out.
• If the fire does not go out at once, stop, get out and close the door behind you.

PASS is the general method for most hand-held extinguishers. Class D, wet chemical, clean agent and wheeled units: follow the label and the manufacturer's instructions. Step by step:`,points:["P = Pull: pull out the safety pin and break the seal","A = Aim: point the nozzle at the base of the fire, not the top of the flames — start from the distance shown on the extinguisher label and move closer only as the fire gets smaller","S = Squeeze: squeeze the handle firmly and steadily","S = Sweep: from side to side, slowly, until the fire goes out","Small extinguishers empty quickly, often in a few seconds; the exact discharge time is on the label — be prepared","Where to stand: the exit route (door) must be behind you","After extinguishing, keep watching the area; if the fire reignites, use PASS again or get out","If the fire does not go out at once or the extinguisher is empty: get out immediately, close the door behind you and make sure 115 has been called"]},{heading:"8. The Right Choice for Offices",body:"The office fire extinguisher plan:",points:["Example for an office: ABC in the corridors, CO₂ near electrical and ICT equipment, and Wet Chemical in the kitchen (if there is one)","Under NFPA 10, in a light (low) hazard area one A unit covers up to 3,000 ft² (about 279 m²), so a 2-A extinguisher covers up to about 557 m² (6,000 ft²); no single extinguisher may cover more than about 1,045 m² (11,250 ft²), and no one should have to walk more than 23 m (75 ft) to reach one. The UK code BS 5306-8 recommends at least two extinguishers on each floor (very small floors excepted). The requirement for Duhok offices is set by the Civil Defense Directorate and is not yet confirmed","Travel distance: no more than 23 meters for Class A, 9 or 15 meters for Class B (depending on the extinguisher rating), 9 meters for Class K (NFPA 10)","On the wall and near doors; the top of the fire extinguisher no higher than 1.5 meters above the floor (for fire extinguishers up to 18 kg — NFPA 10)","Place the fire extinguisher sign (ISO 7010 F001) high up so that it can be seen from a distance","Visual check (monthly, by a designated staff member): in its place, visible and easy to reach; pin and tamper seal intact; label readable and facing out; no damage, rust or leaks; hose and nozzle clear; pressure gauge in the green if there is one. CO₂ extinguishers have no gauge: lift one to feel that it is full","Inspection and maintenance (yearly, by a qualified technician from an approved company)","Recharge: after any use, even a short one, by a qualified technician","6-year maintenance: stored-pressure dry chemical (ABC) extinguishers that need a 12-year hydrostatic test are emptied and checked inside every 6 years (NFPA 10) — this is not replacement of the fire extinguisher","Pressure test of the cylinder (Hydrostatic Test), by type: every 5 years for water, foam (AFFF), CO₂, Wet Chemical and stainless-steel dry chemical extinguishers; every 12 years for stored-pressure dry chemical (ABC) extinguishers with mild steel, brazed brass or aluminum shells. The rules for Duhok are not yet confirmed","Removal from service: a fire extinguisher is taken out of service if it fails an inspection or test, is damaged, obsolete or recalled, has no readable label, or is a non-rechargeable unit past the service life on its label"]}],media:[{kind:"video",src:"media/videos/gov_ext_pass.mp4",title:"The PASS Technique",description:"Practicing the PASS technique"},{kind:"image",src:"media/images/gov_ext_chart.png",title:"Fire Extinguisher Selection Chart",description:"Selection according to the class of fire"}],quiz:[{question:"Which classes is an ABC fire extinguisher suitable for?",options:[{text:"A only",correct:!1},{text:"A + B + C",correct:!0},{text:"B + C only",correct:!1},{text:"D + K",correct:!1}],explanation:"ABC is for Classes A, B and C (monoammonium phosphate) — not for D (metals) and not for K/F (cooking oil)."},{question:"For a server room, which fire extinguisher is suitable?",options:[{text:"ABC powder",correct:!1},{text:"Water",correct:!1},{text:"Clean Agent (FK-5-1-12)",correct:!0},{text:"Foam",correct:!1}],explanation:"A clean agent leaves no residue and does not damage equipment."},{question:"What does P stand for in PASS?",options:[{text:"Push",correct:!1},{text:"Pull",correct:!0},{text:"Point",correct:!1},{text:"Press",correct:!1}],explanation:"P = Pull (pull out the safety pin)."},{question:"According to NFPA 10, the travel distance to a Class A fire extinguisher must not exceed how much?",options:[{text:"10 meters",correct:!1},{text:"23 meters",correct:!0},{text:"50 meters",correct:!1},{text:"100 meters",correct:!1}],explanation:"NFPA 10: up to 23 meters (75 ft) for Class A; for Class B, 9 or 15 meters depending on the extinguisher rating."},{question:"What is the approximate temperature of CO₂ as it leaves the fire extinguisher?",options:[{text:"0°C",correct:!1},{text:"−78°C",correct:!0},{text:"−30°C",correct:!1},{text:"20°C",correct:!1}],explanation:"CO₂ comes out at a temperature of about −78°C — do not touch the horn, so that your hand is not injured by the cold (frostbite)."},{question:"What is the hazard of AFFF foam?",options:[{text:"There is no hazard",correct:!1},{text:"PFAS — environmental damage",correct:!0},{text:"It is very expensive",correct:!1},{text:"It is very cold",correct:!1}],explanation:"AFFF contains fluorinated substances (PFAS) that pose a risk to the environment; fluorine-free foam is the new replacement."}]},{id:19,code:"GOV-119",icon:"HeartHandshake",accent:"#db2777",title:"First Aid for Office Staff",subtitle:"Workplace First Aid — Primary Check + CPR + AED + Common Emergencies",summary:"The complete first aid program for office employees",blocks:[{body:"In an emergency, the first minutes are critical: if the heart stops, brain damage begins after a few minutes, and every minute of delay in CPR and an AED shock reduces the chance of survival. This lesson explains the primary check, CPR in the office, the AED, choking, bleeding, burns and other common emergencies."},{heading:"1. The Primary Check — Danger, Response, Breathing",body:"The first procedure after finding a person who has collapsed or is unresponsive:",points:["Danger: before you approach, check the scene: electricity, fire, gas, traffic? Your safety comes first",'Response: gently shake their shoulders and ask in a loud voice: "Are you all right?"',"If they do not respond: shout for help, call 122 (put the phone on speaker) and send someone to bring an AED","Breathing: for up to 10 seconds, look at the chest to see whether it rises and falls normally","If they are not breathing, or there are only abnormal gasping breaths (Gasping): this is cardiac arrest — start chest compressions immediately","Lay rescuers (non-medical) do not check the pulse — do not waste time checking","If they are breathing normally and no neck or back injury is suspected: place them on their side (Recovery Position), give nothing by mouth and monitor their breathing until the ambulance arrives"]},{heading:"2. CPR in the Office",body:"For employees (non-medical):",points:["Hand position: center of the chest (lower half of the breastbone), one hand on top of the other","Keep your arms straight with your shoulders directly over the chest; push using the strength of your hips and body","Depth: 5–6 cm for all adults","Rate: 100–120 compressions per minute; after each compression, let the chest recoil fully","Ratio: 30 compressions + 2 breaths; if you have not been trained, give chest compressions only (Hands-Only CPR)","If there are two people: switch places every 2 minutes (5 cycles) so that the force of the compressions does not decrease","Do not stop until: an AED arrives and is working, the medical team arrives, or the person clearly regains consciousness","Common mistakes: insufficient depth, insufficient rate, long pauses, and not letting the chest recoil"]},{heading:"3. AED — Automated External Defibrillator",body:"It is recommended that every large government building have one:",points:["Location: in a public, visible corridor, so that it can be reached quickly","Sign: a cabinet with the AED sign (ISO 7010 E010) and clear lighting","Goal: the AED should reach any location in the building within about 3 minutes","Steps: 1) switch it on, 2) place the two pads on the bare chest, 3) follow the voice prompts, 4) if it advises a shock, press the button",'Before the shock, say out loud "Stand clear!" — no one may touch the person',"Monthly inspection: the battery and the expiration date of the pads","After the shock: immediately perform 2 minutes of CPR, then the AED analyzes again","After use: install new pads and batteries so that the device is ready for the next time"]},{heading:"4. Choking",body:"If something is stuck in a person's throat:",points:["Check: can they speak, cough or breathe?","If they are coughing forcefully: encourage them to keep coughing and stay with them","If they cannot speak, cough or breathe: call 122 (or have someone else call) and start immediately","5 back blows: lean them forward and strike firmly between the shoulder blades with the heel of your hand","5 abdominal thrusts (Heimlich): stand behind them, place your fist above the navel and well below the breastbone, grasp it with your other hand and thrust quickly inward and upward","Repeat 5 back blows and 5 abdominal thrusts until the object comes out; if they become unconscious, start CPR","Infants under 1 year old: 5 back blows (head lower than the chest) + 5 chest thrusts with the heel of one hand; never abdominal thrusts","A pregnant woman or a person whose abdomen your arms cannot reach around: chest thrusts instead of abdominal thrusts"]},{heading:"5. Stopping Bleeding (Stop the Bleed)",body:"The three main Stop the Bleed techniques:",points:["1. Direct pressure: place a clean cloth on the wound and press firmly with both hands without stopping","2. Wound packing: for deep wounds (thigh, armpit, neck), pack clean gauze into the wound and press firmly","3. Tourniquet: for life-threatening bleeding from an arm or leg, apply early; 5–7 cm above the wound, not over a joint","Write down the time the tourniquet was applied and never loosen or remove it — only the medical team removes it","Never remove an embedded object from a wound (the bleeding will get worse)","If an object is embedded: wrap cloth around it so that it does not move, and apply pressure around it, not on it","Head wound: apply gentle pressure; if a skull fracture is suspected, do not apply firm pressure","Eye wound: do not press on the eye — only cover it loosely with a clean cloth","For severe bleeding, call 122 immediately; if the cloth becomes soaked with blood, do not remove it — place another one on top"]},{heading:"6. Burns",body:"Burn degrees and total body surface area burned (TBSA):",points:["First degree (superficial): only redness and pain — like sunburn","Second degree (partial thickness): blisters and severe pain","Third degree (full thickness): the skin becomes white, brown or black; there may be no pain because the nerves have been burned","The Rule of Nines (Rule of 9s) for adults: head 9%, each arm 9%, each leg 18%, chest and abdomen 18%, back 18%, genitals 1%","Immediately cool with cool running water for 20 minutes (not ice, not very cold water)","Then cover loosely with plastic wrap (Cling Film) or a clean non-stick cloth","Chemical burns: rinse with running water for at least 20 minutes and check the SDS sheet","Electrical burns: first cut off the power; there is an entry wound and an exit wound, and the internal damage may be greater","Never: ice, oil, cream or toothpaste; do not burst blisters and do not pull off clothing that is stuck to the skin","Call 122 if: the burn is large or deep, it is on the face, hands, feet or genitals, it is an electrical burn, or the person has inhaled smoke"]},{heading:"7. Other Common Emergencies",body:"Common situations in offices:",points:["Fainting: lay them on their back, if they are not injured raise their legs about 30 cm, and let fresh air into the room","Diabetic emergency: if they are conscious and able to swallow, give them sugar or a sweet drink. If they are unconscious: give nothing by mouth, place them on their side and call 122. Give glucagon only if a doctor has prescribed it for them and you have been trained to use it","Panic attack: speak calmly with them and help them breathe slowly; breathing into a paper bag is no longer recommended","Head injury: if a spinal injury is suspected, do not move them unless the place is unsafe or they need CPR (then keep the head, neck and back in line), and do not put them in the recovery position; monitor their consciousness and breathing and call 122","Fracture: splint the limb in the position it was found (Splint), do not straighten it, apply ice wrapped in cloth for the pain and call 122","Electric shock: cut off the power, perform CPR if they are not breathing; everyone must have a heart check (ECG) at the hospital","Poisoning: 1) which substance? 2) how much? 3) when? — call 122, take the substance's container with you, and do not make them vomit","Snake bite: keep the person calm and still and immobilize the limb with a splint; do not tie anything, do not cut and do not suck the blood; call 122 immediately"]}],media:[{kind:"video",src:"media/videos/gov_cpr_workplace.mp4",title:"Workplace CPR",description:"CPR in the workplace"},{kind:"video",src:"media/videos/gov_aed_demo.mp4",title:"AED Demonstration",description:"Using an AED"}],quiz:[{question:"What is the first step in the primary check?",options:[{text:"CPR immediately",correct:!1},{text:"Check for danger",correct:!0},{text:"Call 122",correct:!1},{text:"AED",correct:!1}],explanation:"Before anything else, make sure the scene is safe for you — if you are injured, you cannot help."},{question:"In CPR, what is the compression depth for adults?",options:[{text:"2–3 cm",correct:!1},{text:"5–6 cm",correct:!0},{text:"8–10 cm",correct:!1},{text:"None of these",correct:!1}],explanation:"5–6 cm for all adults (AHA 2025)."},{question:"If an AED shock is delivered within the first 3–5 minutes after collapse, how high can the chance of survival reach?",options:[{text:"10%",correct:!1},{text:"Up to 50–70%",correct:!0},{text:"20%",correct:!1},{text:"100%",correct:!1}],explanation:"An early shock within 3–5 minutes can raise the survival rate to 50–70%; every minute of delay reduces the chance significantly."},{question:"For an infant under 1 year old who is choking (and conscious), what should be done?",options:[{text:"Abdominal thrusts (Heimlich) immediately",correct:!1},{text:"5 back blows + 5 chest thrusts",correct:!0},{text:"Just leave them",correct:!1},{text:"CPR immediately",correct:!1}],explanation:"5 back blows and 5 chest thrusts with the heel of one hand — never abdominal thrusts for infants (AHA 2025)."},{question:"After applying a tourniquet, what must you do?",options:[{text:"Loosen it every 6 hours",correct:!1},{text:"Write down the time it was applied and never loosen it",correct:!0},{text:"Remove it after 10 minutes",correct:!1},{text:"Loosen it every 20 minutes to let blood reach the limb",correct:!1}],explanation:"Write down the time it was applied (Stop the Bleed). The tourniquet stays in place until the medical team removes it; loosening it restarts the bleeding."},{question:"With what kind of water should a burn be cooled for 20 minutes?",options:[{text:"Warm water",correct:!1},{text:"Cool running water, not ice",correct:!0},{text:"Ice",correct:!1},{text:"Medicine and ointment",correct:!1}],explanation:"Cool running water — not warm water (it makes the burn deeper) and not ice (it damages the skin)."}]},{id:20,code:"GOV-120",icon:"Siren",accent:"#2563eb",title:"Civil Defense Operations and Coordination",subtitle:"Civil Defense Operations + ICS + Multi-Agency Response",summary:"The role of the office during a Civil Defense (115) response and coordination with other agencies",blocks:[{body:"Offices must know how to work with Civil Defense (115) during emergencies. The NFPA 1660 standard (into which NFPA 1600 has been consolidated) and the FEMA ICS-100/200 courses are the international foundations. Under ICS, one Incident Commander gives the orders, and all medical, police and firefighting teams and the office work under this command."},{heading:"1. The Incident Command System (ICS)",body:"A unified standard for all agencies:",points:["The ICS-100 and ICS-200 courses are required for key staff","Incident Commander (IC): only one, with overall responsibility for the incident","Five sections: Command, Operations, Planning, Logistics, Finance and Administration (Finance/Admin)","Span of control: 3–7 people for each supervisor (5 is optimal)","Every incident is given its own name (date + location + type)","Plain language: do not use codes or special abbreviations","An Incident Action Plan (IAP) for each operational period, which is generally 12 or 24 hours","If several agencies are responsible: Unified Command — the commanders of the agencies develop one plan together"]},{heading:"2. Calling 115 — What to Say",body:"Stay calm, speak clearly and say these things in this order:",points:["1. The exact location first: the building and the name of the office, the street, a nearby landmark and the floor","2. What happened: fire, explosion, accident, poisoning","3. How many people are hurt or trapped","4. Any danger: fire spreading, gas, electricity, chemicals","5. Your name and your phone number","6. Answer the questions, follow the instructions and do not hang up until they tell you"]},{heading:"3. Multi-Agency Response",body:"When several agencies arrive:",points:["115 Civil Defense: firefighting, rescue, hazardous materials (HazMat)","122 Ambulance: medical treatment and transport","104 Police: securing the perimeter and directing traffic","Electricity department: cutting off the power","Water and gas departments: shutting off water and gas if there is a leak","Ministry of Health: preparing the hospitals","Environmental authority: chemical spills","Emergency Operations Center (EOC) for major incidents"]},{heading:"4. The Role of the Office During an Emergency",body:"What you must do until 115 arrives:",points:["1. Call 115 (and 122 if there are injured people) and give the location first","2. Activate the internal alert (fire alarm or public address system)","3. Staff at the assembly point — headcount (Accountability)","4. Have the building floor plan ready: hazards and the electricity, gas and water shut-off valves","5. Liaison Officer: only one person communicates with 115","6. Have the SDS sheets and contact lists ready","7. Traffic control: keep the route open for emergency vehicles","8. Public Information Officer (PIO): providing information to the public and the media in an organized way","9. Documentation: photos, videos and witness statements","10. Transfer of command: when 115 arrives, command is handed over to the 115 commander"]},{heading:"5. The Office Emergency Response Team (ERT)",body:"Recommended composition:",points:["Incident Commander (IC): the director or deputy director","Alarm coordinator: the fire alarm button and communications","Floor wardens: 2 on every floor, for the evacuation routes","First aid team: 2–3 employees trained in CPR and AED","Search team: checks the rooms and confirms that the building has been evacuated","Fire extinguisher team: employees trained to extinguish small fires at the initial stage","Communications: telephone contact with 115 and internal coordination","Training: initial training and annual refresher"]},{heading:"6. Drills and Testing (Drills + Tabletop Exercises)",body:"Types of exercises (FEMA HSEEP):",points:["Evacuation drill: according to this program, once every 3 months","Tabletop exercise: managers and officers discuss a scenario around a table","Functional exercise: only the teams and key functions (communications, command) are tested","Full-scale exercise (Full-Scale): the whole building and external agencies, at least once a year","Write the After-Action Report (AAR) promptly","Goal: identify what went well, what fell short and what needs to change","Continuous improvement: incorporate the AAR findings into the standard operating procedures (SOP)"]},{heading:"7. The Communication Plan",body:"Without communication, nothing works properly:",points:["Primary: office telephones and the public address system (PA)","Secondary: mobile phones and two-way radios","Tertiary: sending people on foot (Runners)","Backup: satellite phone for major incidents","Testing: every week for the key teams","Telephone list: available 24/7 and kept up to date","For the public: telephone hotline, website and social media — only through the PIO","Note: in major incidents, the mobile network may become congested — SMS messages generally get through better"]},{heading:"8. After-Action Review",body:"The post-incident review:",points:["Recommendation: within 72 hours after every incident, while memories are still fresh","Participation of all parties: IC, operations, logistics and external agencies","4 questions: What was planned? What happened? Why was there a difference? What will we change next time?","Metrics: response time, number of injured, property damage","Documentation: a Lessons Learned report","Updating: SOPs, the Emergency Operations Plan (EOP) and training materials","Follow-up: check implementation after 30, 60 and 90 days","Sharing: share the findings with other agencies"]}],media:[{kind:"video",src:"media/videos/gov_ics_demo.mp4",title:"ICS in Action",description:"ICS in a real disaster"},{kind:"image",src:"media/images/gov_salute_card.png",title:"115 Call Checklist Card",description:"Reminder card: what to say when you call 115"}],quiz:[{question:"In ICS, how many Incident Commanders (IC) are needed?",options:[{text:"3–5",correct:!1},{text:"Only one",correct:!0},{text:"Every employee",correct:!1},{text:"2–4",correct:!1}],explanation:"In ICS there is one Incident Commander. If several agencies are responsible, a Unified Command works under one shared plan."},{question:"When you call 115, what do you say first?",options:[{text:"Your name and your role",correct:!1},{text:"The exact location: the building, the street, a nearby landmark and the floor",correct:!0},{text:"When the incident started",correct:!1},{text:"What equipment you have",correct:!1}],explanation:"Say the exact location first. Then say what happened, how many people are hurt or trapped, any danger, and your name and phone number."},{question:"When 115 arrives, who takes over command?",options:[{text:"The ERT continues",correct:!1},{text:"The 115 commander",correct:!0},{text:"The Liaison Officer (Liaison)",correct:!1},{text:"The police",correct:!1}],explanation:"Transfer of command: when 115 arrives, command is handed over to the 115 commander and the ERT assists them."},{question:"What is a tabletop exercise?",options:[{text:"A full-building evacuation drill",correct:!1},{text:"Discussing a scenario around a table with the officers in charge",correct:!0},{text:"Testing the siren",correct:!1},{text:"Training in using fire extinguishers",correct:!1}],explanation:"A tabletop exercise is a discussion of a scenario without moving people or equipment, in order to test plans and roles (FEMA HSEEP)."},{question:"Within how many hours is it recommended to conduct the After-Action Review (AAR)?",options:[{text:"24",correct:!1},{text:"48",correct:!1},{text:"72",correct:!0},{text:"168",correct:!1}],explanation:"Within 72 hours — while memories are still fresh and complete."},{question:"What is the span of control in ICS?",options:[{text:"2 people",correct:!1},{text:"3–7 people",correct:!0},{text:"10+ people",correct:!1},{text:"Unlimited",correct:!1}],explanation:"According to NIMS: 3–7 people for each supervisor, and 5 is optimal."}]}],t={lessons:e};export{t as default,e as lessons};
